        const batchInfoU32Count = numBatches * GpuVoxelization.BATCH_INFO_U32S;
        this.ensureSlotBuffer(slot, 'batchInfoBuffer', 'batchInfoBufferSize', batchInfoU32Count * 4, BUFFERUSAGE_COPY_DST, 'batchInfos');
